from __future__ import absolute_import
import time
import logging
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException, NoSuchElementException
from taf.selenium.sc.pages.view import ViewPanel
from taf.selenium.sc.pages.navigatable_page import NavigatablePage
from taf.selenium.sc.common.utils import wait_for_operation_success


class Topology(object):
    def __init__(self, driver, download_checker):
        self._hardware = HardWarePage(driver, download_checker)

    @property
    def hardware(self):
        return self._hardware


class HardWarePage(NavigatablePage):
    _MENU_ROUTE_LIST = ["topology", "Hardware"]

    def __init__(self, driver, download_checker):
        super(HardWarePage, self).__init__(driver)
        self._view_panel = HardwareViewPanel(driver, download_checker)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def block_prrh(self, prrh, timeout=60):
        return self._view_panel.block_prrh(prrh, timeout)

    def unblock_prrh(self, prrh, timeout=60):
        return self._view_panel.unblock_prrh(prrh, timeout)

    def reset_prrh(self, prrh, timeout=60):
        return self._view_panel.reset_prrh(prrh, timeout)

    def download_faults_report(self, download_timeout=1800):
        return self._view_panel.download_faults_report(download_timeout)

    def reset_shub(self, shub, timeout=60):
        return self._view_panel.reset_shub(shub, timeout)

    def get_active_fault(self, timeout=60, wait_fault_timeout=30):
        return self._view_panel.get_active_fault(timeout, wait_fault_timeout)

    def get_history_fault(self, timeout=60, wait_fault_timeout=30):
        return self._view_panel.get_history_fault(timeout, wait_fault_timeout)


class HardwareViewPanel(ViewPanel):
    _ARROW_RIGHT = 'Right'
    _TOPOLOGY_EXPAND_BUTTON = '//button[contains(@id, "expand-all")]'
    _PROPERTIES_EXPAND_XPATH = '//*[@id="topologyDetailsArea"]//app-button-bistable'
    _PRRH_MODULE_XPATH = '//app-unit//*[contains(text(), "{}")]'
    _ACTIVE_TAB = '//*[@id="faults-tab-active"]/parent::li'
    _HISTORY_TAB = '//*[@id="faults-tab-history"]/parent::li'
    _FAULT = '//*[@id="faults-table"]//tr[@tabindex="0"]'
    _UNBLOCKED = 'unblocked'
    _BLOCKED = 'blocked'

    def __init__(self, driver, download_checker):
        super(HardwareViewPanel, self).__init__(driver, download_checker)
        self._properties_panel = PropertiesViewPanel(driver)
        self._fault_details_view_panel = FaultDetailsViewPanel(driver, download_checker)

    def _pre_operation(self, module_name, timeout):
        self.click_enabled_element((By.XPATH, self._TOPOLOGY_EXPAND_BUTTON), timeout)
        self._show_property_panel(timeout)
        self.click_enabled_element((By.XPATH, self._PRRH_MODULE_XPATH.format(module_name)), timeout)

    def unblock_prrh(self, prrh, timeout):
        self._pre_operation(prrh, timeout)
        self._properties_panel.unblock_prrh(timeout)
        return self._properties_panel.wait_until_target_local_state_appear(self._UNBLOCKED, 10)

    def block_prrh(self, prrh, timeout):
        self._pre_operation(prrh, timeout)
        self._properties_panel.block_prrh(timeout)
        return self._properties_panel.wait_until_target_local_state_appear(self._BLOCKED, 10)

    def reset_prrh(self, prrh, timeout):
        self._pre_operation(prrh, timeout)
        self._properties_panel.reset_prrh(timeout)
        return self._properties_panel.wait_success_toast_complete(timeout)

    def reset_shub(self, shub, timeout):
        self._pre_operation(shub, timeout)
        self._properties_panel.reset_shub(timeout)
        return self._properties_panel.wait_success_toast_complete(timeout)

    def _show_property_panel(self, timeout=60):
        if self._ARROW_RIGHT not in self.get_attribute_by_xpath(self._PROPERTIES_EXPAND_XPATH, 'icon'):
            self.click_enabled_element((By.XPATH, self._PROPERTIES_EXPAND_XPATH), timeout)

    def get_active_fault(self, timeout, wait_fault_timeout):
        self.click_enabled_element((By.XPATH, self._ACTIVE_TAB), timeout)
        return self._get_fault(timeout, wait_fault_timeout)

    def get_history_fault(self, timeout, wait_fault_timeout):
        self.click_enabled_element((By.XPATH, self._HISTORY_TAB), timeout)
        return self._get_fault(timeout, wait_fault_timeout)

    def _get_fault(self, timeout=60, wait_fault_timeout=30):
        faults = []

        try:
            self.wait_for_visibility_by_xpath(self._FAULT, wait_fault_timeout)
        except TimeoutException:
            return faults

        return self._get_fault_detail(timeout)

    @wait_for_operation_success(2)
    def _get_fault_detail(self, timeout):
        faults = []
        for elem in self.driver.find_elements_by_xpath(self._FAULT):
            try:
                source_elem = elem.find_element_by_xpath('.//td[contains(@class, "Source")]')
            except NoSuchElementException as err:
                """
                if fault table is empty, the element will not be found by xpath.
                so ignore the exception and continue here.
                """
                logging.info("The fault detail xpath not found, ignore and continue, err={}".format(err))
                continue

            source_elem.click()
            fault = self._fault_details_view_panel.get_fault_detail(timeout)
            faults.append({source_elem.text: fault})
        return faults

    def download_faults_report(self, download_timeout=1800):
        return self._fault_details_view_panel.download_faults_report(download_timeout)


class PropertiesViewPanel(ViewPanel):
    _BLOCK_BUTTON = '//button[contains(text(), "Block")]'
    _UNBLOCK_BUTTON = '//button[contains(text(), "Unblock")]'
    _RESET_BUTTON = '//button[contains(text(), "Reset")]'
    _TOAST = '//*[contains(@class, "toast-bottom-right")]//*[contains(@class, "toast-title")]'
    _LOCAL_STATE = '//*[contains(text(), "Local state")]/following-sibling::*//span'
    _SUCCESSFULLY = 'successfully'

    def __init__(self, driver):
        super(PropertiesViewPanel, self).__init__(driver)

    def block_prrh(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._BLOCK_BUTTON), timeout)
        self.wait_for_visibility_by_xpath(self._TOAST, timeout)
        self.wait_success_toast_complete(timeout)

    def unblock_prrh(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._UNBLOCK_BUTTON), timeout)
        self.wait_for_visibility_by_xpath(self._TOAST, timeout)
        self.wait_success_toast_complete(timeout)

    def reset_prrh(self, timeout=90):
        self.click_enabled_element((By.XPATH, self._RESET_BUTTON), timeout)

    def reset_shub(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._RESET_BUTTON), timeout)

    def wait_success_toast_complete(self, timeout=60):
        try:
            self.wait_for_text_present_in_element((By.XPATH, self._TOAST), self._SUCCESSFULLY, timeout)
            self.wait_for_invisibility((By.XPATH, self._TOAST), timeout)
            return True
        except TimeoutException:
            return False

    @wait_for_operation_success(2)
    def _get_module_local_state(self, timeout=10):
        self.wait_for_visibility((By.XPATH, self._LOCAL_STATE), timeout)
        return self.get_text_by_xpath(self._LOCAL_STATE, timeout)

    def wait_until_target_local_state_appear(self, local_state, timeout=60):
        return self._until(lambda _: self._get_module_local_state(timeout) == local_state, timeout)


class FaultDetailsViewPanel(ViewPanel):
    _DETAIL_EXPANSION_PANEL = '//*[@id="faultDetailsContainer"]//mat-expansion-panel'
    _EXPANSION_HEADER = './/*[contains(@id, "mat-expansion-panel-header")]//div'
    _EXPANSION_BODY = './/*[contains(@class, "mat-expansion-panel-body")]'
    _DETAIL_TITLE_ELEMS = _EXPANSION_BODY + '//span[contains(@class, "detail-title")]'
    _DETAIL_TEXT_ELEMS = _EXPANSION_BODY + '//span[contains(@class, "detail-text")]'
    _DOWNLOAD_FAULTS_REPORT_BUTTON = '//*[@id="faults-header"]//button[@*="Download faults report"]'

    def __init__(self, driver, download_checker):
        super(FaultDetailsViewPanel, self).__init__(driver, download_checker)

    @wait_for_operation_success(2)
    def get_fault_detail(self, timeout=60):
        self.wait_for_enable((By.XPATH, self._DETAIL_EXPANSION_PANEL), timeout)
        fault_detail = {}
        for elem in self.driver.find_elements_by_xpath(self._DETAIL_EXPANSION_PANEL):
            title = elem.find_element_by_xpath(self._EXPANSION_HEADER).text
            title_elems = elem.find_elements_by_xpath(self._DETAIL_TITLE_ELEMS)
            text_elems = elem.find_elements_by_xpath(self._DETAIL_TEXT_ELEMS)
            titles = [elem.text.strip(':') for elem in title_elems]
            texts = [elem.text for elem in text_elems]
            body = dict(zip(titles, texts))
            fault_detail.update({title: body})
        return fault_detail

    def download_faults_report(self, download_timeout=1800):
        start_time = time.time()
        self.click_enabled_element((By.XPATH, self._DOWNLOAD_FAULTS_REPORT_BUTTON))
        return self.download_files(start_time, download_timeout)
